FF=fm('τ=τ_ff+K_pE+K_vĖ',{'τ':'actuator torque','τ_ff':'model feedforward torque','E,Ė':'desired-minus-actual joint position and velocity errors','K_p,K_v':'torque-domain feedback gains'},{'τ,τ_ff':'N·m','E':'rad','Ė':'rad/s','K_p':'N·m/rad','K_v':'N·m·s/rad'},['All revolute joints; the feedback terms are not virtual accelerations.'])
