c=concept(738,'Disturbance sign, coupling and steady error','Resisting torque convention, inverse-matrix order, equilibrium assumptions and cross-joint response.')
DIST=fm('Ë+K_vĖ+K_pE=M⁻¹τ_d; E_ss=K_p⁻¹M⁻¹τ_d',{'E,Ė,Ë':'desired-minus-actual error and time derivatives','E_ss':'equilibrium position-error vector','M':'actual inertia at the equilibrium pose','K_p,K_v':'virtual-acceleration feedback gains','τ_d':'disturbance torque subtracted at the actuator/plant summing junction'},{'E,E_ss':'rad','Ė':'rad/s','Ë':'rad/s²','M':'kg·m²','K_p':'s⁻²','K_v':'s⁻¹','τ_d':'N·m'},['Exact cancellation of the nominal model; all revolute joints; M and K_p invertible. Steady formula additionally assumes a constant disturbance and a reached equilibrium with Ė=Ë=0.'])
ask(c,'Why is the disturbance term positive in the slide’s error equation although the diagram subtracts τ_d at the arm input?', ['E is desired minus actual, so reduced actual acceleration increases Ë','The disturbance is actually added to both the reference and the plant','The sign of an error equation is independent of how error is defined','M⁻¹ must have every entry negative'],['With plant acceleration τ′−M⁻¹τ_d, subtracting it from desired acceleration creates the positive forcing.','The diagram shows a single negative torque input, not reference injection.','Reversing the error definition changes the associated signs.','A physical positive-definite inertia inverse need not have all-negative entries.'],difficulty='medium',kind='diagram',formula=[DIST],pages=[731,738],steps=['The diagram yields q̈=q̈_d+K_vĖ+K_pE−M⁻¹τ_d.','Use Ë=q̈_d−q̈ and rearrange.'])
ask(c,'At an equilibrium with constant τ_d, which matrix order follows from K_pE=M⁻¹τ_d?', ['E=K_p⁻¹M⁻¹τ_d','E=M⁻¹K_p⁻¹τ_d for all matrices','E=K_pM⁻¹τ_d','E=M K_pτ_d'],['Premultiply by K_p⁻¹ on the left; matrix factors cannot generally be commuted.','That reversal requires an extra commutation condition not stated.','Solving requires inverse K_p, not K_p.','Both inversions are lost.'],difficulty='medium',formula=[DIST])
ask(c,'Let M=[[2,1],[1,2]] kg·m², K_p=diag(2,4) s⁻² and constant resisting disturbance τ_d=(3,0) N·m. What equilibrium error follows?', ['(1,−0.25) rad','(1,−0.5) rad','(0.75,0) rad','(−1,0.25) rad'],['M⁻¹τ_d=(2,−1) rad/s², then K_p⁻¹ gives (1,−0.25).','This reverses the matrix order, using M⁻¹K_p⁻¹τ_d.','This neglects the off-diagonal inertia.','This reverses the resisting-disturbance sign.'],kind='numerical',difficulty='medium',formula=[DIST],steps=['det M=4−1=3, so M⁻¹=(1/3)[[2,−1],[−1,2]].','M⁻¹(3,0)=(2,−1) rad/s².','Divide by diagonal gains 2 and 4: E_ss=(1,−1/4) rad.'],assumptions=['A stable equilibrium exists and is reached; use the constant matrices supplied at that pose.'])
ask(c,'Which factor does not appear directly in the constant-disturbance equilibrium-error formula?', ['K_v, the velocity-error gain','K_p, the position-error gain','M, the inertia matrix at the pose','τ_d, the disturbance torque'],['At equilibrium Ė=0, so the velocity-feedback term vanishes.','Position feedback balances the disturbance forcing.','Inverse inertia maps the physical disturbance to acceleration forcing.','The disturbance magnitude and direction determine the forcing.'],kind='exception',formula=[DIST])
ask(c,'Select all justified qualifications of the steady-error expression on the slide.', ['It is an equilibrium relation, not the instantaneous error for arbitrary time-varying disturbances','Off-diagonal inertia can transmit one-joint disturbances into other joint errors','It proves every disturbance affects every joint by a nonzero amount at every pose','It requires no invertibility assumptions because inverse symbols are merely notation'],['Setting both error derivatives to zero is essential to the equilibrium derivation.','The matrix multiplication can produce cross-joint components.','Special zeros, directions and poses can eliminate particular couplings.','The displayed inverses require invertible matrices.'],correct=(0,1),kind='statement',difficulty='medium',formula=[DIST])
ask(c,'Which pair consists entirely of disturbance examples named in the lecture?', ['Payload variation and external forces','Exact model cancellation and perfect sensing','Diagonal gain selection and equilibrium error definition','Reference trajectory storage and offline precomputation'],['Both are explicitly listed with friction changes, vibration and unmodeled dynamics.','These are ideal conditions, not the listed disturbances.','These are controller/modeling choices.','These are computation choices rather than disturbance examples.'],kind='definition')
c=concept(739,'Estimated-model residual','Hatted quantities, actual acceleration in residual, exact-model limit and cancellation caveats.')
UNC=fm('Ë+K_vĖ+K_pE=M̂⁻¹[(M−M̂)q̈+(V−V̂)+(G−Ĝ)+(F−F̂)]',{'E,Ė,Ë':'desired-minus-actual errors and derivatives','K_p,K_v':'virtual-acceleration gains','M,M̂':'actual and estimated inertia matrices','q̈':'actual joint acceleration','V,V̂':'actual and estimated velocity-effect torques','G,Ĝ':'actual and estimated gravity torques','F,F̂':'actual and estimated friction/effect torques'},{'E':'rad','Ė':'rad/s','Ë,q̈':'rad/s²','K_p':'s⁻²','K_v':'s⁻¹','M,M̂':'kg·m²','V,V̂,G,Ĝ,F,F̂':'N·m'},['All revolute joints, invertible estimated inertia, continuous controller τ=M̂(q̈_d+K_vĖ+K_pE)+V̂+Ĝ+F̂, no extra disturbance.'])
ask(c,'What does a hat over M, V, G or F indicate on the uncertainty slide?', ['The controller’s estimated model quantity','The transpose of the actual quantity','The time derivative of the actual quantity','An automatically exact measured quantity'],['Hatted terms represent the model used by the controller.','A transpose is a different operation and notation.','The slide uses dots for time derivatives.','The point of the slide is that estimates may differ from the plant.'],kind='definition')
ask(c,'Which acceleration multiplies M−M̂ in the displayed uncertainty residual?', ['Actual joint acceleration q̈','Desired acceleration q̈_d only','Position error E','The integral of velocity error'],['Rearranging the actual plant and estimated controller yields (M−M̂)q̈.','Replacing actual by desired acceleration needs additional algebra and changes the other terms.','Error is an angle, not the acceleration required in this torque product.','Its integral is not the actual acceleration.'],formula=[UNC])
ask(c,'For a scalar joint, M=3 and M̂=2 kg·m², actual q̈=4 rad/s², V−V̂=1, G−Ĝ=2 and F−F̂=−1 N·m. What is the uncertainty forcing in the slide’s error equation?', ['3 rad/s²','2 rad/s²','6 rad/s²','−3 rad/s²'],['The torque mismatch is (3−2)4+1+2−1=6 N·m; dividing by estimated inertia 2 gives 3.','This divides by actual inertia 3 rather than estimated inertia 2.','This stops before applying M̂⁻¹.','This reverses every model-difference sign.'],kind='numerical',difficulty='medium',formula=[UNC],steps=['Inertia mismatch torque=(3−2)×4=4 N·m.','Add other differences:4+1+2−1=6 N·m.','Multiply by M̂⁻¹=1/2 to obtain 3 rad/s².'])
ask(c,'If every hatted model term equals its actual counterpart, what remains of the uncertainty residual?', ['Zero, recovering the ideal homogeneous error equation','M⁻¹G even though gravity is modeled exactly','Twice the actual Coriolis term','Only the desired acceleration error'],['Every difference inside the bracket is zero.','Exact gravity compensation cancels its difference.','Exact velocity-term matching cancels that difference too.','No such residual term is left.'],formula=[UNC],pages=[731,739])
ask(c,'If the uncertainty residual happens to equal zero at one instant, does that prove the entire dynamic model is exact?', ['No; nonzero mismatch terms can cancel at that state and motion','Yes; the sum of mismatches can vanish only if each mismatch vanishes','Yes; one zero residual identifies every mass and friction parameter','No; because even an exactly matched model always has nonzero residual'],['A sum can vanish through cancellation or zero acceleration without every parameter matching.','Independent differences need not each be zero when their weighted sum is zero.','One operating point generally cannot establish all model quantities.','The exactly matched model does give zero residual.'],difficulty='medium',formula=[UNC])
c=concept(740,'Industrial-control tradeoffs','Course-specific rationale and almost-independent control versus actual coupling.')
ask(c,'According to this lecture, why may an industrial controller use simpler joint laws rather than full nonlinear model-based control?', ['Computation cost and incomplete parameters may outweigh the extra performance benefit','Simple laws make all inertial and gravity effects physically disappear','Every robot is mechanically decoupled before any controller is installed','Full model-based control cannot use measured joint positions'],['The source cites computational expense, incomplete knowledge and often adequate simpler performance.','The plant dynamics remain even if the controller does not compensate them.','The lecture explicitly discusses remaining coupling.','Model-based control can use measured states, as earlier diagrams show.'],assumptions=['A course-specific qualitative statement, not a current market-share survey.'])
ask(c,'What does treating each joint almost independently mean in the described architecture?', ['Separate joint feedback loops are used without claiming the physical joints are uncoupled','Every off-diagonal element of the real inertia matrix must be zero','A disturbance on one joint is mathematically unable to affect another','Only one joint is permitted to move at a time'],['Controller organization and physical dynamic coupling are separate issues.','Separate loops do not force the plant inertia to be diagonal.','The lecture warns that coupling and disturbance interactions remain.','The architecture does not impose serial one-joint-at-a-time motion.'],pages=[740,742])
c=concept(741,'Joint PID structure and dimensional scope','Diagonal P/I/D gains, sensor feedback, integral state and missing acceleration-to-torque scaling.')
PID=fm('τ=K_pE+K_vĖ+K_i z; z(t)=z(0)+∫₀ᵗE(s)ds',{'τ':'joint torque command','E,Ė':'desired-minus-actual angle error and derivative','z':'integrated position error including initial state','K_p,K_v,K_i':'proportional, derivative and integral torque-domain gains','s,t':'integration variable and elapsed time'},{'τ':'N·m','E':'rad','Ė':'rad/s','z':'rad·s','K_p':'N·m/rad','K_v':'N·m·s/rad','K_i':'N·m/(rad·s)','s,t':'s'},['Single revolute joint or diagonal componentwise gains; desired-acceleration feedforward set to zero; no separate model compensation.'])
ask(c,'Which pairing matches the three parallel paths in the individual-joint PID diagram?', ['P: error; D: derivative of error; I: integral of error','P: actual torque; D: error integral; I: error derivative','P: error derivative; D: error; I: actual acceleration','P: desired position only; D: actual position only; I: gravity only'],['The diagram explicitly shows K_pe(t), K_v de/dt and K_i∫e dt.','This swaps the derivative and integral actions and changes the proportional input.','It interchanges P and D and replaces the integral path.','The paths act on tracking error, not three unrelated physical signals.'],kind='match',formula=[PID])
ask(c,'What role does the encoder play in the PID block diagram?', ['It returns measured joint motion through the negative-feedback path','It replaces the integral gain with an exact gravity model','It generates desired acceleration from the payload mass','It multiplies the torque command by the full inertia matrix'],['The sensor returns the plant output for comparison with the desired joint position.','No gravity-model block is present in this diagram.','Neither trajectory acceleration nor mass modeling is assigned to the encoder.','The diagram has no inertia-scaling block in the controller.'],kind='diagram')
ask(c,'For E=0.1 rad, Ė=−0.2 rad/s, z=0.5 rad·s, K_p=20 N·m/rad, K_v=3 N·m·s/rad and K_i=4 N·m/(rad·s), what PID torque results with desired-acceleration feedforward set to zero?', ['3.4 N·m','4.6 N·m','1.4 N·m','−0.6 N·m'],['2−0.6+2=3.4 N·m.','This changes the derivative correction sign.','This omits the integral contribution.','This retains only the derivative contribution and omits both P and I.'],kind='numerical',formula=[PID],steps=['P=20(0.1)=2 N·m.','D=3(−0.2)=−0.6 N·m and I=4(0.5)=2 N·m.','Sum to obtain 3.4 N·m.'])
ask(c,'A single-joint integral state starts at z(0)=0 and sees a constant error E=0.2 rad for 3 s. With K_i=5 N·m/(rad·s), what integral torque develops?', ['3 N·m','1 N·m','0.333 N·m','15 N·m'],['z=0.2×3=0.6 rad·s and K_i z=3 N·m.','This multiplies gain by error but omits the integration time.','This divides rather than multiplies by time.','This omits the error magnitude.'],kind='numerical',formula=[PID],steps=['Integrate constant error: z=0+∫₀³0.2 dt=0.6 rad·s.','Multiply by K_i: 5×0.6=3 N·m.'])
ask(c,'The slide sets α=I and includes q̈_d directly in a torque command. For dimensional consistency in ordinary SI joint units with nonzero q̈_d, what must be supplied?', ['An acceleration-to-torque scale such as a nominal inertia, or an explicit normalized-unit convention','Only a change from radians to degrees, with no gain change','A second time integral of the torque command','No explanation, because N·m and rad/s² are the same unit'],['A physical acceleration cannot be added directly to torque unless an appropriate scale or normalization is declared.','Changing angle units does not turn acceleration into torque.','Integrating torque does not repair the stated command’s units.','Torque and angular acceleration have different dimensions.'],difficulty='medium',pages=[730,731,741],conflict=(741,'With α=I the servo expression adds desired angular acceleration to torque-domain PID terms without specifying normalization.','Retain the printed form as source notation, but set the acceleration term to zero for SI numerical PID tasks or explicitly supply a nominal inertia/normalization.'))
ask(c,'With diagonal PID gains, what does the controller omit compared with full computed torque?', ['Full nonlinear inertia/load compensation and exact dynamic decoupling','All feedback of joint position','Every use of a desired position','The proportional, derivative and integral paths'],['The simplified architecture uses independent error feedback rather than the full M,V,G,F cancellation.','The encoder feedback is explicitly present.','Desired position is the input to the error calculation.','Those three paths define the shown PID controller.'],pages=[730,741])
issue(741,'command-units','α=I and unscaled desired acceleration are added to physical torque-domain PID terms; no normalization/inertia scale is stated.','Use desired acceleration zero in SI examples; explicitly test the missing scale rather than silently treat acceleration as torque.')
c=concept(742,'Posture effects and gravity compensation','Fixed-gain tradeoffs, static load balance, estimated gravity and integral-action limits.')
ask(c,'Why are fixed gains described as an average compromise over the workspace?', ['Configuration-dependent dynamics prevent one fixed setting from generally giving ideal critical damping everywhere','Fixed gains mathematically force all postures to have the same inertia','The controller changes every link mass to keep the damping ratio constant','Critical damping is independent of both gains and plant dynamics'],['Changing inertia and coupling changes effective closed-loop dynamics.','Feedback gain selection does not make physical inertia constant.','The controller does not alter link masses.','Damping depends on the gain/dynamics relationship.'],pages=[735,742])
GRAV=fm('K_pE_ss=G−Ĝ; K_i z_ss=G−Ĝ when E_ss=0',{'K_p,K_i':'torque-domain proportional and integral gains','E_ss':'static joint-angle error under PD control','G,Ĝ':'actual and estimated holding gravity torques','z_ss':'constant integral state supplying the residual gravity torque'},{'K_p':'N·m/rad','K_i':'N·m/(rad·s)','E_ss':'rad','G,Ĝ':'N·m','z_ss':'rad·s'},['Scalar revolute joint, constant reference and load, zero acceleration/velocity, no other loads; first relation uses PD without integral, second uses stable unsaturated PID at zero error.'])
ask(c,'A static scalar joint uses PD feedback plus Ĝ=3 N·m; actual gravity is G=5 N·m and K_p=20 N·m/rad. What holding error E=q_d−q balances the residual load?', ['0.10 rad','0.25 rad','0.40 rad','−0.10 rad'],['K_pE=G−Ĝ=2 N·m, so E=2/20=0.10 rad.','This ignores the gravity estimate.','This adds actual and estimated gravity.','This reverses the desired-minus-actual error balance.'],kind='numerical',formula=[GRAV],assumptions=['No integral action, motion or other torque terms; a reachable static equilibrium is assumed.'],steps=['Static plant torque is G=5 N·m.','Controller torque is 20E+3 N·m.','Solve 20E+3=5 to obtain E=0.10 rad.'])
ask(c,'Does gravity necessarily cause nonzero final position error with ideal PID?', ['No; stable unsaturated integral action can supply constant gravity torque while final error is zero','Yes; even an exact integral controller must retain G/K_p position error','No; because gravity is zero whenever velocity is zero','Yes; a gravity estimate makes zero steady error impossible'],['At a zero-error equilibrium the integral state can remain nonzero and supply the required torque.','G/K_p describes an uncompensated proportional static balance, not every PID equilibrium.','Gravity is generally a static load.','A gravity estimate can reduce the integral torque needed.'],difficulty='medium',pages=[741,742],formula=[PID,GRAV],assumptions=['Constant reference and gravity load; a stable equilibrium exists, with no actuator saturation, integrator leakage or windup limitation.'],conflict=(742,'The slide states Gravity creates steady-state error immediately after displaying a PID law.','A stable unsaturated ideal integral controller can balance constant gravity at zero error; finite PD error and practical PID limitations must be distinguished.'))
ask(c,'At zero position error, let actual gravity be 5 N·m, the compensation estimate 3 N·m and K_i=4 N·m/(rad·s). What constant integral state supplies the remaining torque?', ['0.5 rad·s','1.25 rad·s','2 rad·s','0 rad·s'],['The remaining 2 N·m divided by K_i=4 gives z=0.5 rad·s.','This ignores the existing 3 N·m compensation.','This confuses remaining torque with integral state.','Zero integral state would leave a 2 N·m deficit.'],kind='numerical',formula=[GRAV],pages=[741,742],steps=['Residual gravity is 5−3=2 N·m.','At zero error, P and D are zero.','Solve 4z=2 to obtain z=0.5 rad·s.'],assumptions=['A stable unsaturated static PID equilibrium has been reached; desired acceleration is zero.'])
issue(742,'pid-steady-error','Gravity creates steady-state error is overbroad for the displayed ideal PID architecture.','Distinguish PD residual error from PID integral-state load balance, with stability and actuator-limit assumptions stated.')
